META = dict(nama="Shipbuilding", jp="造船・舶用工業", emoji="🚢", co="造船所")
SPEC = dict(kerja="安全と品質を大切にして、大きな船を作っている", kerja_id="membuat kapal besar dengan mengutamakan keselamatan dan kualitas", soal={
 "shibou-01": ("なぜ造船の仕事を選びましたか。", "Mengapa Anda memilih pekerjaan pembuatan kapal?", "私の国は島が多くて、船が生活に大切です。大きい船を作る仕事に、あこがれていました。", "Negara saya banyak pulau dan kapal penting bagi kehidupan. Saya mengagumi pekerjaan membuat kapal besar.", [("造船", "pembuatan kapal"), ("船", "kapal"), ("島", "pulau"), ("あこがれる", "mengagumi")]),
 "shibou-02": ("なぜ日本で造船を学びたいですか。", "Mengapa Anda ingin belajar pembuatan kapal di Jepang?", "日本の造船は、技術が高くて、品質がとても良いと聞きました。その技術を学んで、将来に生かしたいです。", "Saya dengar pembuatan kapal Jepang berteknologi tinggi dan berkualitas sangat baik. Saya ingin mempelajarinya dan memanfaatkannya kelak.", [("技術", "teknologi"), ("品質", "kualitas"), ("生かす", "memanfaatkan")]),
 "shibou-04": ("この仕事に興味を持った理由は何ですか。", "Apa alasan Anda tertarik pada pekerjaan ini?", "みんなで協力して、大きいものを作ることに、魅力を感じます。完成した船が海に出るのを見たいです。", "Saya tertarik pada kerja sama membuat sesuatu yang besar. Saya ingin melihat kapal jadi berlayar ke laut.", [("協力", "kerja sama"), ("完成", "selesai"), ("魅力", "daya tarik")]),
 "shibou-05": ("造船の仕事で、一番楽しみなことは何ですか。", "Apa yang paling Anda nantikan dari pekerjaan pembuatan kapal?", "船が完成して、進水するときの喜びです。溶接などの技術も学びたいです。", "Kegembiraan saat kapal selesai dan diluncurkan. Saya juga ingin belajar teknik seperti pengelasan.", [("進水", "peluncuran kapal"), ("溶接", "pengelasan"), ("楽しみ", "dinantikan")]),
 "shigoto-01": ("造船の主な仕事は何だと思いますか。", "Menurut Anda, apa pekerjaan utama pembuatan kapal?", "鉄の板を切ったり、溶接したり、塗装したりして、船を作る仕事だと思います。", "Saya kira pekerjaannya memotong pelat besi, mengelas, dan mengecat untuk membuat kapal.", [("溶接", "pengelasan"), ("塗装", "pengecatan"), ("鉄板", "pelat besi")]),
 "shigoto-02": ("朝早くから働くことはできますか。", "Apakah Anda bisa bekerja dari pagi buta?", "はい、できます。早く寝て、朝の準備をしっかりします。", "Ya, bisa. Saya tidur lebih awal dan bersiap dengan baik di pagi hari.", [("早起き", "bangun pagi"), ("準備", "persiapan"), ("体調", "kondisi badan")]),
 "shigoto-03": ("暑い日や寒い日でも、外や船の中で働けますか。", "Bisakah Anda bekerja di luar atau di dalam kapal walau panas atau dingin?", "はい、大丈夫です。夏はこまめに水を飲んで、冬は服をたくさん着ます。", "Ya, tidak masalah. Saat musim panas saya sering minum air, saat dingin memakai banyak lapis pakaian.", [("暑い", "panas"), ("寒い", "dingin"), ("こまめに", "sering/rutin")]),
 "shigoto-04": ("高い所や、せまい所で作業することがありますが、大丈夫ですか。", "Ada pekerjaan di tempat tinggi atau sempit, apakah Anda baik-baik saja?", "はい、大丈夫です。安全帯などをつけて、安全の決まりを守って作業します。", "Ya, tidak masalah. Saya memakai sabuk pengaman dan bekerja sesuai aturan keselamatan.", [("高所", "tempat tinggi"), ("せまい", "sempit"), ("安全帯", "sabuk pengaman")]),
 "shigoto-05": ("体力が必要な仕事ですが、大丈夫ですか。", "Pekerjaan ini butuh stamina, apakah Anda baik-baik saja?", "はい、大丈夫です。毎日運動をして、体力をつけています。重いものは、一人で持たないようにします。", "Ya, tidak masalah. Saya berolahraga setiap hari. Barang berat tidak saya angkat sendirian.", [("体力", "stamina"), ("重い", "berat"), ("運動", "olahraga")]),
 "shigoto-06": ("船の完成の前など、忙しいとき、残業があっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan lembur saat sibuk, misalnya menjelang kapal selesai?", "はい、大丈夫です。忙しい時期は、チームでがんばります。体調にも気をつけます。", "Ya, tidak masalah. Saat sibuk kami berusaha bersama. Saya juga menjaga kondisi badan.", [("残業", "lembur"), ("完成", "selesai"), ("チーム", "tim")]),
 "shigoto-07": ("溶接や、機械を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat mengelas dan memakai mesin?", "必ず使い方を教えてもらってから使います。保護めんや手袋をつけて、まわりに燃えやすいものがないか確認します。", "Saya memakainya hanya setelah diajari cara pakainya. Saya memakai pelindung wajah dan sarung tangan, serta memeriksa tidak ada benda mudah terbakar di sekitar.", [("保護めん", "pelindung wajah"), ("火花", "percikan api"), ("確認", "memastikan")]),
 "shigoto-08": ("火花や、大きい音、においがある環境でも大丈夫ですか。", "Apakah Anda baik-baik saja di lingkungan dengan percikan api, suara keras, dan bau?", "はい、大丈夫です。必要なときは、耳せんやマスクをつけます。", "Ya, tidak masalah. Bila perlu saya memakai penyumbat telinga dan masker.", [("火花", "percikan api"), ("騒音", "kebisingan"), ("マスク", "masker")]),
 "shigoto-09": ("船を作る仕事で、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting dalam membuat kapal?", "安全と、正確さだと思います。船は海で使うので、小さい間違いが大きい事故になることがあります。", "Menurut saya, keselamatan dan ketelitian. Karena kapal dipakai di laut, kesalahan kecil bisa menjadi kecelakaan besar.", [("正確", "akurat"), ("事故", "kecelakaan"), ("安全", "keselamatan")]),
 "shigoto-10": ("船ができるまで、どんな作業がありますか。", "Pekerjaan apa saja sampai kapal selesai dibuat?", "鉄の板を切って、組み立てて、溶接します。そのあと、塗装をして、機械を入れて、検査をします。", "Pelat besi dipotong, dirakit, dan dilas. Setelah itu dicat, mesin dipasang, lalu diperiksa.", [("組み立て", "perakitan"), ("検査", "inspeksi"), ("塗装", "pengecatan")]),
 "shigoto-11": ("図面を見て、作業することはできますか。", "Apakah Anda bisa bekerja sambil membaca gambar kerja?", "まだ難しいところもありますが、勉強しています。分からないところは、すぐに先輩に聞きます。", "Masih ada bagian sulit, tetapi saya sedang belajar. Bagian yang tidak paham segera saya tanyakan kepada senior.", [("図面", "gambar kerja"), ("勉強", "belajar"), ("先輩", "senior")]),
 "shigoto-12": ("クレーンで、重いものを動かすとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memindahkan barang berat dengan derek?", "吊っているものの下には、入りません。合図をする人の指示を、必ず守ります。", "Saya tidak masuk ke bawah barang yang digantung. Saya selalu mematuhi instruksi petugas pemberi isyarat.", [("クレーン", "derek"), ("吊る", "menggantung"), ("合図", "isyarat")]),
 "shigoto-13": ("寸法や、数を測ったり、確認したりする作業は、得意ですか。", "Apakah Anda pandai mengukur dan memeriksa ukuran dan jumlah?", "はい、得意です。ミスをしないように、二回確認します。分からないときは、先輩に聞きます。", "Ya, saya pandai. Agar tidak salah, saya memeriksa dua kali. Kalau tidak paham, saya bertanya kepada senior.", [("寸法", "ukuran"), ("測る", "mengukur"), ("確認", "memastikan")]),
 "taiou-02": ("部品を間違って、つけてしまったら、どうしますか。", "Apa yang Anda lakukan kalau keliru memasang bagian?", "すぐに正直に報告します。どうして間違えたか考えて、次は図面を二回確認します。", "Saya segera melapor jujur. Saya memikirkan penyebabnya dan lain kali memeriksa gambar kerja dua kali.", [("部品", "bagian/suku cadang"), ("図面", "gambar kerja"), ("報告", "melapor")]),
 "taiou-06": ("雨や風で、仕事の予定が急に変わったら、どうしますか。", "Apa yang Anda lakukan kalau rencana kerja mendadak berubah karena hujan atau angin?", "責任者の指示をよく聞いて、安全を第一に動きます。わからないときは、すぐに聞きます。", "Saya mendengarkan instruksi penanggung jawab dan bergerak dengan mengutamakan keselamatan. Kalau tidak paham, saya langsung bertanya.", [("急に", "mendadak"), ("指示", "instruksi"), ("安全第一", "keselamatan utama")]),
 "taiou-08": ("溶接のあとで、不良に気づいたら、どうしますか。", "Apa yang Anda lakukan kalau menyadari cacat setelah pengelasan?", "勝手に直さないで、すぐに先輩に報告します。やり方を教えてもらって、直します。", "Saya tidak memperbaikinya sembarangan, segera melapor kepada senior. Saya diajari caranya lalu memperbaiki.", [("不良", "cacat"), ("報告", "melapor"), ("直す", "memperbaiki")]),
 "taiou-11": ("忙しい時期で、疲れているとき、どう気持ちを保ちますか。", "Bagaimana Anda menjaga semangat saat sibuk dan lelah?", "忙しい時期は短いと理解しています。しっかり寝て、食事をとって、体調を保ちます。", "Saya paham musim sibuk itu singkat. Saya tidur cukup, makan baik, dan menjaga kondisi badan.", [("疲れる", "lelah"), ("体調", "kondisi badan"), ("睡眠", "tidur")]),
 "taiou-12": ("先輩の説明が専門用語ばかりで、分からないとき、どうしますか。", "Apa yang Anda lakukan kalau penjelasan senior penuh istilah teknis yang tidak Anda pahami?", "「すみません、この言葉の意味を教えてください」と聞きます。メモして、あとで復習します。", "Saya bertanya \"Maaf, tolong jelaskan arti kata ini\". Saya mencatatnya dan mengulang pelajaran nanti.", [("専門用語", "istilah teknis"), ("意味", "arti"), ("復習", "mengulang pelajaran")]),
 "tim-01": ("大きい部品を運ぶとき、チームの人と、どのように作業しますか。", "Saat memindahkan bagian besar, bagaimana Anda bekerja dengan tim?", "声をかけ合って、合図を決めてから運びます。責任者の指示で、役割を分けます。", "Kami saling memberi aba-aba dan menentukan isyarat sebelum memindahkan. Peran dibagi sesuai instruksi penanggung jawab.", [("合図", "isyarat"), ("役割", "peran"), ("声をかけ合う", "saling memberi aba-aba")]),
 "tim-02": ("先輩の指示が分からなかったとき、どうしますか。", "Apa yang Anda lakukan kalau tidak paham instruksi senior?", "すぐに「もう一度お願いします」と聞きます。分からないまま作業すると、とても危ないからです。", "Saya segera meminta \"Tolong ulangi\". Bekerja tanpa paham sangat berbahaya.", [("指示", "instruksi"), ("危ない", "berbahaya"), ("確認", "memastikan")]),
 "tim-03": ("いろいろな会社や、職人さんと、どのようにコミュニケーションをとりますか。", "Bagaimana Anda berkomunikasi dengan berbagai perusahaan dan tukang?", "元気にあいさつをします。作業の予定や、危ない所を、お互いに確認し合います。", "Saya menyapa dengan semangat. Kami saling memastikan rencana kerja dan tempat berbahaya.", [("職人", "tukang ahli"), ("あいさつ", "salam"), ("確認し合う", "saling memastikan")]),
 "tim-04": ("造船所の仲間と、どのように仲良くなりたいですか。", "Bagaimana Anda ingin akrab dengan rekan di galangan kapal?", "毎日、元気にあいさつをします。教えてもらったときは、「ありがとうございます」と言います。", "Setiap hari saya menyapa dengan semangat. Saat diajari, saya mengatakan \"Terima kasih\".", [("あいさつ", "salam"), ("仲間", "rekan"), ("仲良くなる", "menjadi akrab")]),
 "anzen-01": ("造船所で、必ず身につけるものは何ですか。", "Apa yang wajib dikenakan di galangan kapal?", "ヘルメット、安全靴、保護めがね、手袋を必ず着けます。高い所では、安全帯も使います。", "Saya wajib memakai helm, sepatu keselamatan, kacamata pelindung, dan sarung tangan. Di tempat tinggi saya juga memakai sabuk pengaman.", [("ヘルメット", "helm"), ("安全帯", "sabuk pengaman"), ("安全靴", "sepatu keselamatan")]),
 "anzen-02": ("溶接をするとき、火事ややけどを防ぐために、何をしますか。", "Apa yang Anda lakukan saat mengelas untuk mencegah kebakaran dan luka bakar?", "まわりに燃えやすいものがないか、確認します。保護めんと手袋をつけます。作業のあとで、火が残っていないか見ます。", "Saya memeriksa tidak ada benda mudah terbakar di sekitar. Saya memakai pelindung wajah dan sarung tangan. Setelah kerja saya memastikan tidak ada bara yang tertinggal.", [("火事", "kebakaran"), ("保護めん", "pelindung wajah"), ("やけど", "luka bakar")]),
 "anzen-03": ("高い所で作業するとき、何に気をつけますか。", "Apa yang Anda perhatikan saat bekerja di tempat tinggi?", "安全帯をかけて、足元をよく見ます。道具を落とさないように、ひもでつなぎます。", "Saya memasang sabuk pengaman dan memperhatikan pijakan. Alat saya ikat dengan tali agar tidak jatuh.", [("安全帯", "sabuk pengaman"), ("足元", "pijakan"), ("落とす", "menjatuhkan")]),
 "anzen-04": ("せまい船の中で作業するとき、何に気をつけますか。", "Apa yang Anda perhatikan saat bekerja di ruang sempit dalam kapal?", "空気が足りているか、確認します。必ず二人以上で作業して、中の人と声をかけ合います。", "Saya memastikan udara cukup. Saya bekerja minimal berdua dan saling berkomunikasi dengan orang di dalam.", [("換気", "ventilasi"), ("酸欠", "kekurangan oksigen"), ("声をかけ合う", "saling memberi aba-aba")]),
 "seikatsu-07": ("海の近くの町での生活に、不便なことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan ketidaknyamanan hidup di kota pesisir?", "大丈夫です。寮から造船所までの行き方を、調べておきます。休みの日は、買い物や勉強をします。", "Tidak masalah. Saya akan mengecek rute dari asrama ke galangan. Saat libur saya berbelanja dan belajar.", [("寮", "asrama"), ("通勤", "berangkat kerja"), ("まとめて", "sekaligus")]),
 "seikatsu-08": ("日本の船や、造船について、知っていることはありますか。", "Apa yang Anda ketahui tentang kapal dan pembuatan kapal di Jepang?", "日本は、昔から造船が盛んな国だと聞きました。大きいタンカーや、船の機械も作っていると知っています。", "Saya dengar Jepang sejak dulu negara dengan industri kapal yang maju. Saya tahu mereka membuat kapal tanker besar dan mesin kapal.", [("盛ん", "maju/berkembang"), ("タンカー", "kapal tanker"), ("昔から", "sejak dulu")]),
 "mokuhyou-05": ("日本で造船を学んだあと、自分の国でどんなことをしたいですか。", "Setelah belajar pembuatan kapal di Jepang, apa yang ingin Anda lakukan di negara sendiri?", "日本で学んだ溶接や、安全の方法を使って、自分の国の造船の仕事で、役に立ちたいです。", "Saya ingin berguna di pekerjaan pembuatan kapal di negara saya dengan memakai pengelasan dan cara keselamatan yang saya pelajari di Jepang.", [("溶接", "pengelasan"), ("安全", "keselamatan"), ("役に立つ", "berguna")]),
})
